# Shipment (Before Save): container numbers, chargeable weight and volume, destination filings.
# Written for the Server Script sandbox: no import, no class, no .format, no += on items or attributes.


def iso6346_ok(code):
    """ISO 6346 container number: 4 letters, 6 digits and a check digit."""
    code = (code or "").replace(" ", "").replace("-", "").upper()
    if len(code) != 11 or not code[4:].isdigit() or not code[:4].isalpha():
        return False
    values = {}
    n = 10
    for ch in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        if n % 11 == 0:
            n = n + 1
        values[ch] = n
        n = n + 1
    total = 0
    for i in range(10):
        v = values[code[i]] if i < 4 else int(code[i])
        total = total + v * (2 ** i)
    return (total % 11) % 10 == int(code[10])


u = frappe.utils

# 1. container numbers: warn, never block (a mistyped number is fixed on the bill of lading)
for c in doc.get("apparel_containers") or []:
    if c.container_no and c.container_type != "LCL part" and c.container_type != "Air ULD" and not iso6346_ok(c.container_no):
        frappe.msgprint(f"Container {c.container_no} does not pass the ISO 6346 check digit. Check it against the bill of lading.", indicator="orange")

# 2. chargeable weight (air) and volume (sea): the greater of actual and volumetric
divisor = u.flt(frappe.db.get_single_value("Apparel Settings", "air_volumetric_divisor")) or 6000
gross = 0
volume_cm3 = 0
for p in doc.get("shipment_parcel") or []:
    count = u.cint(p.count)
    gross = gross + u.flt(p.weight) * count
    volume_cm3 = volume_cm3 + u.flt(p.length) * u.flt(p.width) * u.flt(p.height) * count
mode = doc.get("apparel_mode") or ""
if mode == "Air":
    doc.apparel_chargeable_kg = round(max(gross, volume_cm3 / divisor), 2)
elif mode.startswith("Sea"):
    doc.apparel_chargeable_cbm = round(max(volume_cm3 / 1000000.0, gross / 1000.0), 3)

# 3. destination filings: one row per enabled rule that applies to this country, mode and incoterm
country = doc.get("apparel_destination_country")
if country and mode:
    have = [r.rule for r in (doc.get("apparel_filings") or []) if r.rule]
    for rule in frappe.get_all("Destination Filing Rule", {"enabled": 1, "country": country},
                               ["name", "filing_name", "mode", "hours_before_loading", "incoterms", "filed_by"]):
        if rule.name in have:
            continue
        mode_ok = (not rule.mode) or rule.mode == "Any" or mode.startswith(rule.mode)
        wanted = [x.strip() for x in (rule.incoterms or "").split(",") if x.strip()]
        if mode_ok and ((not wanted) or (doc.get("incoterm") in wanted)):
            due = None
            if doc.get("apparel_cutoff"):
                due = u.add_to_date(doc.apparel_cutoff, hours=-u.cint(rule.hours_before_loading))
            doc.append("apparel_filings", {"rule": rule.name, "filing_name": rule.filing_name, "due_by": due, "filed_by": rule.filed_by})

late = []
now = u.now_datetime()
for r in doc.get("apparel_filings") or []:
    if r.due_by and not r.filed_on and u.get_datetime(r.due_by) < now:
        late.append(r.filing_name)
if late:
    frappe.msgprint("Filing overdue: " + ", ".join(late), indicator="red", title="Destination filings")

# Supplier Quotation used as a freight quote (Before Validate): quantity against the shipment, minimum and maximum charges, at-cost lines.
u = frappe.utils
sh = None
if doc.get("apparel_shipment"):
    sh = frappe.db.get_value("Shipment", doc.apparel_shipment, ["apparel_declared_cbm", "apparel_declared_gross_kg", "apparel_chargeable_kg"], as_dict=True)

for it in doc.items:
    unit = it.get("apparel_charge_unit")
    if not unit:
        continue
    qty = u.flt(it.qty)
    if unit == "At Cost":
        it.rate = 0
        if "(at cost" not in (it.description or ""):
            it.description = (it.description or "") + " (at cost: not in the total)"
        continue
    if sh:
        want = None
        if unit == "Per CBM":
            want = u.flt(sh.apparel_declared_cbm)
        elif unit == "Per kg":
            want = u.flt(sh.apparel_chargeable_kg) or u.flt(sh.apparel_declared_gross_kg)
        elif unit == "Per HBL" or unit == "Per Shipment":
            want = 1
        if want and abs(qty - want) > max(0.01, want * 0.01):
            frappe.msgprint(f"{it.item_code}: quoted on {qty} but the shipment has {want} ({unit}).", indicator="orange", title="Freight quote")
    amount = qty * u.flt(it.rate)
    minimum = u.flt(it.get("apparel_min_amount"))
    maximum = u.flt(it.get("apparel_max_amount"))
    if qty and minimum and amount < minimum:
        it.rate = minimum / qty
    elif qty and maximum and amount > maximum:
        it.rate = maximum / qty

# Scheduler (daily): remind about credits that expire or must be presented soon.
u = frappe.utils
today = u.getdate(u.nowdate())
for lc in frappe.get_all("Letter of Credit", {"status": "Open"}, ["name", "lc_no", "expiry_date", "presentation_deadline", "owner"]):
    for label, day, within in (("expires", lc.expiry_date, 14), ("documents must be presented", lc.presentation_deadline, 5)):
        if not day:
            continue
        left = u.date_diff(day, today)
        if 0 <= left <= within:
            marker = f"[lc-{lc.name}-{label}-{day}]"
            if not frappe.db.exists("ToDo", {"reference_type": "Letter of Credit", "reference_name": lc.name, "description": ["like", "%" + marker + "%"]}):
                frappe.get_doc({"doctype": "ToDo", "allocated_to": lc.owner, "reference_type": "Letter of Credit", "reference_name": lc.name,
                                "description": f"L/C {lc.lc_no} {label} in {left} day(s), on {day}. {marker}"}).insert(ignore_permissions=True)

# Shipment (After Save and After Save of a submitted document): stamp ON_BOARD and IN_WAREHOUSE on the order's T&A.
def stamp(doc, code, day):
    # a milestone cannot be stamped with a date in the future; a planned date stays on the shipment until it has happened
    if not day or frappe.utils.getdate(day) > frappe.utils.getdate(frappe.utils.nowdate()):
        return
    for row in doc.get("apparel_packing_lists") or []:
        card = frappe.db.get_value("Packing List", row.packing_list, "production_card")
        c = frappe.db.get_value("Production Card", card, ["sales_order", "style_item"], as_dict=True) if card else None
        if not c:
            continue
        for t in frappe.get_all("Order TNA", {"sales_order": c.sales_order, "style_item": c.style_item, "status": ["!=", "Cancelled"]}, ["name"]):
            for m in frappe.get_all("TNA Milestone", {"order_tna": t.name, "milestone_type": code}, ["name", "actual_date", "source_doctype", "source_name"]):
                if not m.actual_date or (m.source_doctype == "Shipment" and m.source_name == doc.name):
                    ms = frappe.get_doc("TNA Milestone", m.name)
                    ms.actual_date = day
                    ms.source_doctype = "Shipment"
                    ms.source_name = doc.name
                    ms.save(ignore_permissions=True)


stamp(doc, "ON_BOARD", doc.get("apparel_on_board_date"))
stamp(doc, "IN_WAREHOUSE", doc.get("apparel_delivery_date"))

