# API Server Script `arinox_engine`: the production ledger and its flow rules, in one place, for a site that cannot import code.
# Document scripts call it with run_script("arinox_engine", action=..., ...). The app's reference implementation is
# production/ledger.py + production/flow.py; the same tests are the specification.
#
# actions:  post   card, rows (JSON), source_doctype, source_name, posting_date, override (0/1), check (0/1)
#           unpost source_doctype, source_name
#           total  card, stage, colour, size, purpose        -> frappe.flags.arinox_total
#           check  card, rows (JSON), override                -> raises if a row exceeds its limit
# Everything sits inside main(): in the sandbox module-level functions cannot see each other.

def main():
    form = frappe.form_dict
    action = form.get("action")
    STAGES = ("CUT", "CUT_REJECT", "SEW_IN", "SEW_OUT", "SEW_REJECT", "SC_OUT", "SC_BACK_GOOD", "SC_BACK_REJECT_VENDOR",
              "SC_BACK_REJECT_FACTORY", "FIN_IN", "FIN_A", "FIN_B", "FIN_REJECT", "SAMPLE_OUT", "PACKED", "SHIPPED")
    REJECT_STAGES = ("CUT_REJECT", "SEW_REJECT", "SC_BACK_REJECT_VENDOR", "SC_BACK_REJECT_FACTORY", "FIN_REJECT")
    CUT_PURPOSES = ("Bulk", "Pilot", "Sample")
    STATUS_BY_STAGE = (("SHIPPED", "Shipped"), ("PACKED", "Packed"), ("FIN_IN", "In Finishing"), ("SC_OUT", "At Subcontractor"),
                       ("SEW_IN", "In Sewing"), ("CUT", "In Cutting"))

    def num(n):
        if float(n) == int(n):
            return str(int(n))
        return str(round(n, 2))

    def sval(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        if v is None or v == "":
            return default
        return v

    def repair_accepted(card, colour, size):
        r = frappe.db.sql(
            "select ifnull(sum(r.accepted_for_repair), 0) from `tabSubcontract Return Row` r "
            "join `tabSubcontract Return` p on p.name = r.parent "
            "where p.docstatus = 1 and r.production_card = %s and r.colour = %s and r.size = %s", (card, colour, size))
        return r[0][0] or 0

    def make_flow(card):
        """Totals of one card, loaded once; limit() and apply() answer and absorb rows so a document's rows count together."""
        doc = frappe.get_doc("Production Card", card)
        T = {}
        for r in frappe.db.sql(
                "select colour, size, stage, ifnull(purpose, ''), ifnull(subcontract_process, ''), sum(qty) from `tabProduction Movement` "
                "where production_card = %s group by colour, size, stage, purpose, subcontract_process", card):
            T[r[0], r[1], r[2], r[3], r[4]] = r[5] or 0
        lines = {}
        for l in doc.lines:
            lines[l.colour, l.size] = l
        route = sorted(doc.processes, key=lambda p: (0 if p.position == "Before Sewing" else 1, int(p.sequence or 0), p.idx))

        def t(colour, size, stage, purpose=None, process=None):
            total = 0
            for k in T:
                if k[0] == colour and k[1] == size and k[2] == stage:
                    if (purpose is None or k[3] == purpose) and (process is None or k[4] == process):
                        total = total + T[k]
            return total

        def apply(row):
            k = (row["colour"], row["size"], row["stage"], row.get("purpose") or "Bulk", row.get("process") or "")
            T[k] = T.get(k, 0) + row["qty"]

        def good_cut(colour, size):
            return t(colour, size, "CUT") - t(colour, size, "CUT_REJECT")

        def route_for(colour, position):
            out = []
            for p in route:
                c = (p.colour or "").strip()
                if p.position == position and (not c or c.upper() == colour.strip().upper()):
                    out.append(p)
            return out

        def back_good(colour, size, process):
            return t(colour, size, "SC_BACK_GOOD", process=process)

        def after_output(colour, size):
            after = route_for(colour, "After Sewing")
            if after:
                return back_good(colour, size, after[-1].subcontract_process)
            return t(colour, size, "SEW_OUT")

        def limit(row):
            """(max qty the row may add, 'block' or 'warn'), or (None, None) when no rule applies."""
            stage = row["stage"]
            colour = row["colour"]
            size = row["size"]
            purpose = row.get("purpose") or "Bulk"
            process = row.get("process") or ""
            if stage == "CUT":
                line = lines.get((colour, size))
                if purpose == "Re-cut":
                    lost = 0
                    for s in REJECT_STAGES:
                        lost = lost + t(colour, size, s)
                    return lost - t(colour, size, "CUT", purpose="Re-cut"), "block"
                if not line:
                    frappe.throw("%s %s is not on production card %s." % (colour, size, card))
                cap = (line.planned_cut_qty or 0) + int(sval("cut_cap_extra_pcs", 3))
                done = 0
                for p in CUT_PURPOSES:
                    done = done + t(colour, size, "CUT", purpose=p)
                mode = sval("cut_cap_mode", "Block")
                if mode == "Off":
                    return None, None
                return cap - done, ("warn" if mode == "Warn" else "block")
            if stage == "SEW_IN":
                avail = good_cut(colour, size)
                for p in route_for(colour, "Before Sewing"):
                    avail = min(avail, back_good(colour, size, p.subcontract_process))
                return avail - t(colour, size, "SEW_IN"), "block"
            if stage == "SEW_OUT" or stage == "SEW_REJECT":
                return t(colour, size, "SEW_IN") - t(colour, size, "SEW_OUT") - t(colour, size, "SEW_REJECT"), "block"
            if stage == "SC_OUT":
                full = route_for(colour, "Before Sewing") + route_for(colour, "After Sewing")
                names = [p.subcontract_process for p in full]
                if process not in names:
                    frappe.throw("%s is not on the route of production card %s for colour %s." % (process, card, colour))
                i = names.index(process)
                before = full[i].position == "Before Sewing"
                if i == 0 or full[i - 1].position != full[i].position:
                    prior = good_cut(colour, size) if before else t(colour, size, "SEW_OUT")
                else:
                    prior = back_good(colour, size, full[i - 1].subcontract_process)
                return prior - t(colour, size, "SC_OUT", process=process), "block"
            if stage == "FIN_IN":
                return after_output(colour, size) + repair_accepted(card, colour, size) - t(colour, size, "FIN_IN"), "block"
            if stage == "FIN_A" or stage == "FIN_B" or stage == "FIN_REJECT":
                return t(colour, size, "FIN_IN") - t(colour, size, "FIN_A") - t(colour, size, "FIN_B") - t(colour, size, "FIN_REJECT"), "block"
            if stage == "SAMPLE_OUT" or stage == "PACKED":
                return t(colour, size, "FIN_A") - t(colour, size, "SAMPLE_OUT") - t(colour, size, "PACKED"), "block"
            if stage == "SHIPPED":
                return t(colour, size, "PACKED") - t(colour, size, "SHIPPED"), "block"
            return None, None   # SC_BACK_* are limited per challan row by the Subcontract Return itself

        def check(rows, override):
            problems = []
            for row in rows:
                if row["qty"] > 0 and not override:
                    lim = limit(row)
                    if lim[0] is not None and row["qty"] > lim[0] + 0.000000001:
                        msg = "%s: %s %s %s - %s entered, %s available." % (
                            row["stage"], row["colour"], row["size"], row.get("process") or "", num(row["qty"]), num(max(lim[0], 0)))
                        if lim[1] == "warn":
                            frappe.msgprint(msg, indicator="orange", title="Production Flow")
                        else:
                            problems.append(msg)
                apply(row)
            if problems:
                frappe.throw("<br>".join(problems), title="Production Flow")

        return {"check": check, "t": t}

    def clean_rows(rows):
        out = []
        for r in rows:
            if not r.get("qty"):
                continue
            if r["stage"] not in STAGES:
                frappe.throw("Unknown production stage %s." % r["stage"])
            row = dict(r)
            row["colour"] = (r.get("colour") or "").strip()
            row["size"] = (r.get("size") or "").strip()
            row["qty"] = float(r["qty"])
            if not row.get("purpose"):
                row["purpose"] = "Bulk"
            out.append(row)
        return out

    def refresh_card_status(card):
        """Card status follows the furthest stage that has quantities. Closed, Superseded and Cancelled cards are left alone."""
        row = frappe.db.get_value("Production Card", card, ["docstatus", "status"], as_dict=True)
        if not row or row.docstatus != 1 or row.status in ("Superseded", "Cancelled", "Closed"):
            return
        present = [r[0] for r in frappe.db.sql("select distinct stage from `tabProduction Movement` where production_card = %s", card)]
        status = "Issued"
        for pair in STATUS_BY_STAGE:
            if pair[0] in present:
                status = pair[1]
                break
        if status != row.status:
            frappe.db.set_value("Production Card", card, "status", status, update_modified=False)

    def post():
        card = form.get("card")
        rows = clean_rows(json.loads(form.get("rows") or "[]"))
        if not rows:
            return
        if int(form.get("check") or 1):
            make_flow(card)["check"](rows, int(form.get("override") or 0))
        head = frappe.db.get_value("Production Card", card, ["sales_order", "style_item"], as_dict=True)
        when = frappe.utils.getdate(form.get("posting_date") or frappe.utils.nowdate())
        for r in rows:
            mv = frappe.get_doc({
                "doctype": "Production Movement", "production_card": card, "sales_order": head.sales_order, "style_item": head.style_item,
                "colour": r["colour"], "size": r["size"], "stage": r["stage"], "purpose": r["purpose"],
                "subcontract_process": r.get("process") or None, "qty": r["qty"], "posting_date": when, "line": r.get("line") or None,
                "supplier": r.get("supplier") or None, "shade_band": r.get("shade_band") or None,
                "fault_source": r.get("fault_source") or None, "source_doctype": form.get("source_doctype"),
                "source_name": form.get("source_name"), "source_row": r.get("source_row")})
            mv.insert(ignore_permissions=True, ignore_links=True)    # the source document is mid-submit; the ledger never blocks on it
        refresh_card_status(card)

    def unpost():
        src = form.get("source_doctype")
        name = form.get("source_name")
        cards = [r[0] for r in frappe.db.sql(
            "select distinct production_card from `tabProduction Movement` where source_doctype = %s and source_name = %s", (src, name))]
        for mv in frappe.get_all("Production Movement", {"source_doctype": src, "source_name": name}, pluck="name"):
            frappe.delete_doc("Production Movement", mv, force=1, ignore_permissions=True)
        for c in cards:
            refresh_card_status(c)

    def transfer():
        """A revision of a production card keeps the history: every ledger row and stage document that points at the old card is
        pointed at the new one. Submitted documents are not edited, only their link moves."""
        old = form.get("old")
        new = form.get("new")
        if not old or old == new:
            return
        done = []
        for dt in frappe.get_all("DocField", {"fieldname": "production_card", "fieldtype": "Link", "options": "Production Card"}, pluck="parent"):
            if dt == "Production Card" or dt == "Production Card Line" or dt in done:
                continue
            done.append(dt)
            for n in frappe.get_all(dt, {"production_card": old}, pluck="name"):
                frappe.db.set_value(dt, n, "production_card", new, update_modified=False)

    if action == "transfer":
        transfer()
    elif action == "post":
        post()
    elif action == "unpost":
        unpost()
    elif action == "check":
        make_flow(form.get("card"))["check"](clean_rows(json.loads(form.get("rows") or "[]")), int(form.get("override") or 0))
    elif action == "total":
        f = make_flow(form.get("card"))
        frappe.flags.arinox_total = f["t"](form.get("colour"), form.get("size"), form.get("stage"), form.get("purpose") or None)
    else:
        frappe.throw("arinox_engine: unknown action %s" % action)


main()

# Production Adjustment, Before Save: a manager's correction of a counting mistake needs an open card, a quantity and a reason.
def run(doc):
    card = frappe.db.get_value("Production Card", doc.production_card, ["docstatus", "status"], as_dict=True)
    if not card or card.docstatus != 1 or card.status in ("Superseded", "Cancelled", "Closed"):
        frappe.throw("Production card %s must be issued and open." % doc.production_card)
    if not frappe.utils.flt(doc.qty):
        frappe.throw("Enter a quantity other than zero.")
    if not (doc.reason or "").strip():
        frappe.throw("Enter the reason for the adjustment.")
    if doc.stage in ("SC_OUT", "SC_BACK_GOOD", "SC_BACK_REJECT_VENDOR", "SC_BACK_REJECT_FACTORY") and not doc.subcontract_process:
        frappe.throw("Choose the process for stage %s." % doc.stage)
    if not frappe.db.exists("Production Card Line", {"parent": doc.production_card, "colour": doc.colour, "size": doc.size}):
        frappe.throw("%s %s is not on production card %s." % (doc.colour, doc.size, doc.production_card))


run(doc)

# Production Adjustment, Before Submit: a negative adjustment cannot take off more than the ledger holds.
def run(doc):
    qty = frappe.utils.flt(doc.qty)
    if qty < 0:
        out = run_script("arinox_engine", action="total", card=doc.production_card, stage=doc.stage, colour=doc.colour, size=doc.size,
                         purpose=doc.purpose or "Bulk")
        have = out.get("arinox_total") or 0
        if have + qty < -0.000000001:
            frappe.throw("Only %s recorded for %s; cannot take off %s." % (have, doc.stage, abs(qty)))


run(doc)

# Production Card, Before Save (validate): check the order, fill the header, compute the lines, fabrics and route, set pilot rules.
def run(doc):
    # shared helpers: pure production maths (production/maths.py)
    def planned_cut(order_qty, extra_pct):
        q = float(order_qty or 0)
        if q <= 0:
            return 0
        return int(frappe.utils.ceil(round(q * (1 + float(extra_pct or 0) / 100.0), 6)))


    def max_ship_qty(order_qty, tolerance_pct):
        return int(frappe.utils.floor(round(float(order_qty or 0) * (1 + float(tolerance_pct or 0) / 100.0), 6)))


    def norm(text):
        return (text or "").strip().upper()


    def to_metres(qty, uom, gsm, width_cm):
        kind = {"m": "m", "meter": "m", "metre": "m", "mtr": "m", "mtrs": "m", "meters": "m", "metres": "m", "yd": "yd", "yds": "yd",
                "yard": "yd", "yards": "yd", "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg"}.get((uom or "").strip().lower())
        q = frappe.utils.flt(qty)
        if kind == "m":
            return q
        if kind == "yd":
            return q * 0.9144
        if kind == "kg":
            if not frappe.utils.flt(gsm) or not frappe.utils.flt(width_cm):
                frappe.throw("GSM and cuttable width are needed to convert kg to metres.")
            return q * 1000 / (frappe.utils.flt(gsm) * frappe.utils.flt(width_cm) / 100)
        frappe.throw("Cannot convert UOM %s to metres. Use Meter, Yard or Kg for fabric." % uom)


    def my_roles():
        return frappe.get_all("Has Role", {"parent": frappe.session.user, "parenttype": "User"}, pluck="role")


    def has_any_role(names):
        mine = my_roles()
        for n in names:
            if n in mine:
                return True
        return False
    # shared helpers: the order matrix and style dates (production_card.order_matrix, sample_approval.get_style_dates)
    def order_matrix(sales_order, style_item):
        """({(colour, size): {order_qty, tolerance_pct}}, earliest ex-factory date, [buyer POs]) for one style on an order."""
        cells = {}
        ex_factory = None
        pos = []
        for it in frappe.get_all("Sales Order Item", {"parent": sales_order},
                                 ["item_code", "qty", "apparel_colour", "apparel_size", "apparel_buyer_po", "apparel_qty_tolerance_pct", "delivery_date"]):
            style = frappe.db.get_value("Item", it.item_code, "variant_of") or it.item_code
            if style != style_item:
                continue
            key = ((it.apparel_colour or "").strip(), (it.apparel_size or "").strip())
            if key not in cells:
                cells[key] = {"order_qty": 0, "tolerance_pct": 0}
            cells[key]["order_qty"] = cells[key]["order_qty"] + int(it.qty or 0)
            cells[key]["tolerance_pct"] = max(frappe.utils.flt(cells[key]["tolerance_pct"]), frappe.utils.flt(it.apparel_qty_tolerance_pct))
            if it.delivery_date and (not ex_factory or frappe.utils.getdate(it.delivery_date) < frappe.utils.getdate(ex_factory)):
                ex_factory = frappe.utils.getdate(it.delivery_date)
            if it.apparel_buyer_po and it.apparel_buyer_po not in pos:
                pos.append(it.apparel_buyer_po)
        return cells, ex_factory, pos


    def get_pcd(sales_order, style_item):
        """Planned cut date from the Factory Allocation, then the contract line."""
        if not sales_order:
            return None
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": sales_order}, "name")
        if fa:
            for r in frappe.get_all("Factory Allocation Line", {"parent": fa, "style_item": style_item}, ["pcd"], order_by="pcd"):
                if r.pcd:
                    return r.pcd
        contract = frappe.db.get_value("Sales Order", sales_order, "apparel_sales_contract")
        if contract:
            for r in frappe.get_all("Sales Contract Item", {"parent": contract, "style_item": style_item}, ["pcd"], order_by="pcd"):
                if r.pcd:
                    return r.pcd
        return None


    def setting(field, default):
        v = frappe.db.get_single_value("Apparel Settings", field)
        if v is None or v == "":
            return default
        return v
    flt = frappe.utils.flt
    cint = frappe.utils.cint

    so = frappe.db.get_value("Sales Order", doc.sales_order, ["docstatus", "customer", "company"], as_dict=True)
    if not so or so.docstatus != 1:
        frappe.throw("Sales Order %s must be submitted." % doc.sales_order)
    if so.customer != doc.customer:
        frappe.throw("Sales Order %s belongs to %s, not %s." % (doc.sales_order, so.customer, doc.customer))
    if so.company != doc.company:
        frappe.throw("Sales Order %s belongs to company %s." % (doc.sales_order, so.company))

    # ---- header
    item = frappe.db.get_value("Item", doc.style_item, ["item_name"], as_dict=True)
    if not item:
        frappe.throw("Style item %s not found." % doc.style_item)
    tp = frappe.db.get_value("Tech Pack", {"style_item": doc.style_item}, ["style_no", "style_name", "season"], as_dict=True)
    doc.style_name = doc.style_name or (tp.style_name if tp else None) or item.item_name
    doc.style_no = doc.style_no or (tp.style_no if tp else None) or doc.style_item
    contract = frappe.db.get_value("Sales Order", doc.sales_order, "apparel_sales_contract")
    doc.sales_contract = contract
    doc.season = doc.season or (frappe.db.get_value("Sales Contract", contract, "season") if contract else None) or (tp.season if tp else None)
    matrix = order_matrix(doc.sales_order, doc.style_item)
    cells = matrix[0]
    doc.buyer_pos = "\n".join(matrix[2])
    doc.ex_factory_date = doc.ex_factory_date or matrix[1]
    doc.pcd = doc.pcd or get_pcd(doc.sales_order, doc.style_item)
    if doc.default_extra_cut_pct is None or doc.default_extra_cut_pct == "":
        doc.default_extra_cut_pct = flt(setting("default_extra_cut_pct", 5))
    if doc.trim_allowance_pct is None or doc.trim_allowance_pct == "":
        doc.trim_allowance_pct = flt(setting("trim_allowance_pct", 2))
    doc.bundle_size = cint(doc.bundle_size) or cint(setting("bundle_size", 20))
    if not doc.factory or not doc.line:
        fa = frappe.db.get_value("Factory Allocation", {"sales_order": doc.sales_order}, "name")
        if fa:
            rows = frappe.get_all("Factory Allocation Line", {"parent": fa, "style_item": doc.style_item}, ["factory", "line"], limit=1)
            if rows:
                doc.factory = doc.factory or rows[0].factory
                doc.line = doc.line or rows[0].line
    doc.made_by = doc.made_by or frappe.session.user
    if cint(doc.revision_no) > 0 and not (doc.revision_reason or "").strip():
        frappe.throw("Enter the reason for this revision.")

    # ---- one live card per order x style x ex-factory date (a revision chain shares the key)
    others = frappe.get_all("Production Card", {"sales_order": doc.sales_order, "style_item": doc.style_item, "ex_factory_date": doc.ex_factory_date,
                                                 "docstatus": 1, "status": ["not in", ["Superseded", "Cancelled"]], "name": ["!=", doc.name or ""]}, pluck="name")
    others = [n for n in others if n != doc.previous_card]
    if others:
        frappe.throw("Production card %s already covers this order, style and ex-factory date. Use Revise on it." % others[0])

    # ---- lines
    flags = []
    if not cells:
        frappe.throw("Style %s has no lines on Sales Order %s." % (doc.style_item, doc.sales_order))
    seen = []
    max_extra = flt(setting("max_extra_cut_pct", 8))
    is_manager = has_any_role(["Apparel Production Manager", "Apparel Merchandising Manager", "System Manager"])
    for r in doc.lines:
        key = ((r.colour or "").strip(), (r.size or "").strip())
        if key in seen:
            frappe.throw("Row %s: %s %s appears twice." % (r.idx, key[0], key[1]))
        seen.append(key)
        cell = cells.get(key)
        if not cell:
            frappe.throw("Row %s: %s %s is not on Sales Order %s. Check the colour and size spelling." % (r.idx, key[0], key[1], doc.sales_order))
        r.colour = key[0]
        r.size = key[1]
        r.order_qty = cell["order_qty"]
        r.max_qty = max_ship_qty(cell["order_qty"], cell["tolerance_pct"])
        if r.extra_cut_pct is None or r.extra_cut_pct == "":
            r.extra_cut_pct = doc.default_extra_cut_pct
        if flt(r.extra_cut_pct) < 0:
            frappe.throw("Row %s: extra cut cannot be negative." % r.idx)
        if flt(r.extra_cut_pct) > max_extra:
            if not is_manager:
                frappe.throw("Row %s: extra cut %s%% is above the limit of %s%%. A production manager can allow it." % (r.idx, r.extra_cut_pct, max_extra))
            flags.append("Extra cut above %s%% on %s %s." % (max_extra, r.colour, r.size))
        r.planned_cut_qty = planned_cut(r.order_qty, r.extra_cut_pct)
    for key in cells:
        if key not in seen:
            flags.append("%s %s is on the Sales Order but not on this card." % (key[0], key[1]))
    source = doc.name if (doc.name and not doc.is_new()) else doc.previous_card
    if source:
        cut_over = []
        for r in doc.lines:
            done = frappe.db.sql("select ifnull(sum(qty),0) from `tabProduction Movement` where production_card=%s and colour=%s and size=%s and stage='CUT' and purpose != 'Re-cut'",
                                 (source, r.colour, r.size))[0][0]
            if done > r.planned_cut_qty:
                cut_over.append("%s %s: cut %s > plan %s" % (r.colour, r.size, int(done), r.planned_cut_qty))
        if cut_over:
            flags.append("Cut exceeds the revised plan: " + "; ".join(cut_over))

    # ---- fabrics
    def colour_cut(colour):
        total = 0
        for l in doc.lines:
            if norm(l.colour) == norm(colour):
                total = total + cint(l.planned_cut_qty)
        return total

    for r in doc.fabrics:
        if flt(r.consumption) <= 0:
            frappe.throw("Fabric row %s: consumption must be above zero." % r.idx)
        on_card = False
        for l in doc.lines:
            if norm(l.colour) == norm(r.colour):
                on_card = True
        if not on_card:
            frappe.throw("Fabric row %s: colour %s is not on the size breakup." % (r.idx, r.colour))
        gsm = None
        width = None
        if r.fabric_item:
            vals = frappe.db.get_value("Item", r.fabric_item, ["apparel_fabric_gsm", "apparel_fabric_width_cm"])
            if vals:
                gsm = vals[0]
                width = vals[1]
        per_garment_m = to_metres(flt(r.consumption), r.consumption_uom or "Meter", gsm, width)
        r.required_m = round(colour_cut(r.colour) * per_garment_m, 3)
        if r.fabric_requisition_item:
            fr = frappe.db.get_value("Fabric Requisition Item", r.fabric_requisition_item, ["net_qty", "accepted_qty"], as_dict=True)
            if fr:
                r.fr_net_m = flt(fr.net_qty)
                r.accepted_m = flt(fr.accepted_qty)
                if r.fr_net_m and r.required_m > r.fr_net_m * 1.01:
                    flags.append("%s %s: card needs %s m but the requisition covers %s m." % (r.colour, r.fabric_item or "", round(r.required_m, 1), round(r.fr_net_m, 1)))
        if r.fabric_item and doc.name and not doc.is_new():
            moved = frappe.db.sql("select ifnull(sum(d.qty), 0) from `tabStock Entry Detail` d join `tabStock Entry` s on s.name = d.parent "
                                  "where s.docstatus = 1 and s.apparel_production_card = %s and s.apparel_issue_kind = 'Fabric Issue' and d.item_code = %s",
                                  (doc.name, r.fabric_item))
            r.issued_m = flt(moved[0][0])
        r.shortage_m = round(max(flt(r.required_m) - flt(r.accepted_m), 0), 3) if r.accepted_m else flt(r.required_m)
        if r.shortage_m > 0 and doc.docstatus == 1:
            flags.append("%s: %s m of fabric still to be accepted." % (r.colour, round(r.shortage_m, 1)))

    # ---- route
    route_seen = []
    for p in doc.processes:
        key = (p.subcontract_process, (p.colour or "").strip().upper())
        if key in route_seen:
            frappe.throw("Process %s appears twice on the route." % p.subcontract_process)
        route_seen.append(key)
        info = frappe.db.get_value("Subcontract Process", p.subcontract_process, ["default_position", "item_state"], as_dict=True)
        if not p.item_state and info:
            p.item_state = info.item_state
        if p.position == "Before Sewing" and p.item_state == "Garments":
            frappe.throw("%s: garments cannot go out before sewing; choose Cut Panels or After Sewing." % p.subcontract_process)
        if p.position == "After Sewing" and p.item_state == "Cut Panels":
            frappe.throw("%s: cut panels cannot be sent after sewing; choose Garments or Before Sewing." % p.subcontract_process)

    # ---- pilot run
    total = 0
    for r in doc.lines:
        total = total + cint(r.order_qty)
    by_qty = total >= cint(setting("pilot_min_order_qty", 1000))
    rule = frappe.db.get_value("Apparel Sample Rule", {"parent": "Apparel Settings", "sample_type": "Pilot Run"}, "gate")
    doc.pilot_required = 1 if (by_qty or rule == "Required") else 0
    if cint(doc.pilot_waiver):
        if not has_any_role(["Apparel Production Manager", "System Manager"]) and doc.has_value_changed("pilot_waiver"):
            frappe.throw("Only a production manager can waive the pilot run.")
        if not (doc.pilot_waiver_reason or "").strip():
            frappe.throw("Enter the reason for waiving the pilot run.")
    unique = []
    for f in flags:
        if f not in unique:
            unique.append(f)
    doc.red_flags = "\n".join(unique)


run(doc)

# Production Card, Before Submit: the breakup is required; list what is still open (it never blocks issuing).
