# Delivery Note, After Cancel: take SHIPPED back out of the ledger and reopen the packing lists.
def run(doc):
    lists = []
    for it in doc.items:
        if it.get("apparel_packing_list") and it.apparel_packing_list not in lists:
            lists.append(it.apparel_packing_list)
